def parent_path_fwd(dist, peid, pnode, src):
    """steps (eid, target) of the walk from a distance-0 node down to src"""
    chain = []
    w = src
    while dist[w] > 0:
        chain.append((peid[w], w))
        w = pnode[w]
    chain.reverse()
    return chain, w


def parent_path_back(dist, peid, pnode, src):
    """steps (eid, target) of the walk from src up to a distance-0 node"""
    chain = []
    w = src
    while dist[w] > 0:
        chain.append((peid[w], pnode[w]))
        w = pnode[w]
    return chain, w


